 while(offset<bytes.size()){const auto n=::read(fd,bytes.data()+offset,bytes.size()-offset);need(n>0,"bounded input read failed");offset+=size_t(n);}
 need(::fstat(fd,&after)==0&&same(before,after),"input changed while reading");check();
